function createStore(initial) {
  let current = initial;
  const listeners = new Map();

  return {
    get: () => current,
    set(next) {
      const prev = current;
      current = { ...current, ...next };
      for (const [key, fns] of listeners) {
        if (prev[key] !== current[key]) {
          fns.forEach(fn => fn(current[key]));
        }
      }
    },
    subscribe(key, fn) {
      listeners.set(key, (listeners.get(key) ?? new Set()).add(fn));
      fn(current[key]);          // initial render
    }
  };
}

